@startuml

enum AttendeeStatus {
  Yes
  Maybe
  No
}

enum TaskStatus {
  ToBeDone
  Done
  NotApplicable
}

class Person {
  + FirstName : string
  + LastName : string
  + EmailAddress : string
  + Password : string
}

class Organizer extends Person {
  + PostalAddress : string
  + PhoneNumber : string
}

class Attendee extends Person {
}

class Event {
  + StartDateTime : datetime
  + EndDateTime : datetime
  + Occasion : string
}

class EventType {
  + Name : string
}

class Location {
  + Name : string
  + Address : string
}

class Task {
  + Description : string
}

class ChecklistItem {
  + Status : TaskStatus
}

class Assignment {
}

class Invitation {
  + Status : AttendeeStatus
}

Organizer "1..*" -- "1" Event : manages
Organizer "0..*" -- "0..*" Attendee : invites
Organizer "0..*" -- "0..*" Event : attends
Attendee "0..*" -- "0..*" Event : attends

Event "1" -- "1" EventType : has
Event "1" -- "1" Location : at
Event "1" *-- "*" ChecklistItem : has

Task "1" -- "0..*" ChecklistItem : is used in
Task "0..*" -- "0..*" Event : available for

ChecklistItem "0..1" -- "0..1" Attendee : assigned to
ChecklistItem "1" -- "1" Assignment : involves

@enduml

